// Страница из фикстур: данные `@map` и `@map-alt` подменяются в тестовом файле
// (process-map-9mn.34).
//
// ЗАЧЕМ. Юнит-тесты идут на странице snp (UNIT_TEST_MAP в scripts/mapTarget.ts),
// и то, есть ли у неё вторая версия, решает конфигурация сборки, а не тесты:
// сегодня есть (inplan-model), после process-map-9mn.20 не будет. Тесты
// МЕХАНИКИ версий — переключение, `?version=` в адресе, изоляция правок,
// пересчёт вида — от этого зависеть не должны: им нужна страница, на которой
// версий ровно две и обе известны тесту. Такую страницу собирает этот файл.
//
// Тесты, проверяющие НАСТОЯЩЕЕ содержание snp, сюда не переезжают и остаются
// на настоящей странице.
//
// ЧТО ПОДМЕНЯЕТСЯ, А ЧТО НЕТ. Подменяются только два JSON-модуля. versions.ts,
// loader.ts, store и весь App работают по-настоящему: встроенные версии остаются
// встроенными (свой ключ правок, никакого бейджа «Загруженная схема»), в отличие
// от обходного пути через applyImportedMap(), который показал бы фикстуру как
// чужой файл.
//
// ─── КАК ПОДКЛЮЧАТЬ — ДОСЛОВНО ТАК, В САМОМ ТЕСТОВОМ ФАЙЛЕ ────────────────────
//
//   vi.mock('@map/process.json', async () =>
//     (await import('./fixtures/pageMocks')).defaultVersionModule(),
//   );
//   vi.mock('@map-alt/process.json', async () =>
//     (await import('./fixtures/pageMocks')).altVersionModule(),
//   );
//
// Константы и фабрики ниже в самих тестах импортируются обычным `import`.
//
// Три правила, и каждое проверено, а не предположено:
//
//  1. vi.mock пишется В ТЕСТОВОМ ФАЙЛЕ, а не в функции отсюда. Vitest поднимает
//     вызов в начало того файла, где он написан, — и только поэтому подмена
//     успевает раньше, чем кто-то импортирует versions.ts. Вызов внутри функции
//     помощника выполнился бы тогда, когда до него дойдёт исполнение, то есть
//     в зависимости от порядка импортов.
//  2. Фабрика берёт данные ДИНАМИЧЕСКИМ импортом. Статически импортированное
//     имя в фабрике работает, только пока его `import` стоит в файле ВЫШЕ того,
//     который тянет versions.ts; поменяй строки местами — и Vitest падает с
//     «Cannot access '__vi_import_1__' before initialization» (проверено на
//     Vitest 2.1). Порядок импортов не держит ни Prettier, ни читатель.
//  3. Этот файл НЕ импортирует src/data/versions.ts и ничего, что тянет его
//     (loader, store, App). Фабрика исполняется ВО ВРЕМЯ загрузки versions.ts;
//     обратный импорт замкнул бы кольцо на недогруженном модуле.
//
// ПОЧЕМУ ДВА ВЫЗОВА НЕ СЛИВАЮТСЯ В ОДИН. vi.mock подменяет модуль по
// РАЗРЕШЁННОМУ id, а у страницы без второй версии оба алиаса ведут в один
// каталог. Без отдельной меры второй vi.mock лёг бы поверх первого, и страница
// из двух фикстур молча стала бы страницей из одной. Эта мера — суффикс
// `?<имя алиаса>` в vitest.config.ts: у каждого алиаса свой id модуля.
import type { ProcessMap } from '../../src/data/schema.ts';
import { buildSampleProcessMap } from './sample-process.ts';
import { buildThreeLevelProcessMap } from './three-level-process.ts';

/**
 * Версия по умолчанию страницы из фикстур — id двухуровневой фикстуры.
 * Вычисляется из неё же, а не пишется второй раз: разъехаться им негде.
 */
export const FIXTURE_DEFAULT_ID: string = buildSampleProcessMap().id;

/** Вторая версия страницы из фикстур. */
export const FIXTURE_ALT_ID = 'fixture-alt';

/** Модуль JSON в том виде, в каком его отдаёт Vite: данные — в `default`. */
export interface JsonModule {
  readonly default: ProcessMap;
}

/**
 * Версия по умолчанию: двухуровневая фикстура как есть — четыре этапа.
 *
 * Свежая на каждый вызов (фабрика фикстуры отдаёт новые объекты), поэтому
 * ожидаемые значения в тесте можно считать из неё же, не боясь, что
 * приложение их испортило.
 */
export function fixtureDefaultVersion(): ProcessMap {
  return buildSampleProcessMap();
}

/**
 * Вторая версия: трёхуровневая фикстура БЕЗ modules и moduleEdges и со своим id.
 *
 * ПОЧЕМУ ТРЁХУРОВНЕВАЯ. В ней семь этапов против четырёх у версии по
 * умолчанию, то есть есть номер этапа, которого в первой версии нет вовсе, —
 * на этом стоит проверка «этап ищется в той версии, что названа в адресе». И id
 * узлов у неё другие (`stage-N-input`, `stage-N-step-1`), поэтому узел второй
 * версии в первой не найдётся.
 *
 * ПОЧЕМУ БЕЗ МОДУЛЕЙ. Механика версий от числа уровней не зависит, а тесты
 * здесь смотрят на обзор этапов: заголовок, бейдж с числом этапов, `?stage=N`.
 * Карта с модулями по мере эпика M8 начнёт открываться экраном модулей, и
 * эти тесты молча стали бы проверять другой экран.
 *
 * ПОЧЕМУ СВОЙ id. Версии различаются по id (versions.ts сравнивает именно
 * его); id самой трёхуровневой фикстуры принадлежит ей, и тест, который
 * найдёт его на странице, должен означать трёхуровневую карту, а не эту.
 */
export function fixtureAltVersion(): ProcessMap {
  // Поля УБИРАЮТСЯ, а не обнуляются: «модулей нет» схема выражает отсутствием
  // поля, пустой список она отвергает (tests/moduleSchema.test.ts).
  const map: ProcessMap = { ...buildThreeLevelProcessMap(), id: FIXTURE_ALT_ID };
  delete map.modules;
  delete map.moduleEdges;
  return map;
}

/** Для фабрики vi.mock('@map/process.json', …) — см. шапку файла. */
export function defaultVersionModule(): JsonModule {
  return { default: fixtureDefaultVersion() };
}

/** Для фабрики vi.mock('@map-alt/process.json', …) — см. шапку файла. */
export function altVersionModule(): JsonModule {
  return { default: fixtureAltVersion() };
}
